  const localizationValidationScript = `<script>(()=>{if(document.documentElement.lang!=="en")return;const errors={"有効なURLを入力してください。":"Enter a valid URL.","有効な短縮パスを入力してください。":"Enter a valid short path.","切替日時が正しくありません。":"The switch time is invalid.","転送先の切替には、切替後URLと切替日時の両方を入力してください。":"Enter both the destination after switching and the switch time.","切替後の転送先URLが有効ではありません。":"The destination after switching is invalid.","公開開始日時が正しくありません。":"The availability time is invalid.","共有期限が正しくありません。":"The expiration time is invalid.","上限到達後の転送を使うには、利用回数の上限を設定してください。":"Set a usage limit to use the after-limit redirect.","上限到達後の転送先URLが有効ではありません。":"The destination after the limit is invalid.","合言葉は256文字以内にしてください。":"The passphrase must be 256 characters or fewer.","SNSプレビューの設定が正しくありません。":"The social preview setting is invalid.","転送先のOG情報を取得できませんでした。HTTPSの公開HTMLページを指定してください。":"Could not fetch preview data from the destination. Use a public HTTPS HTML page.","指定プレビューにはタイトルと説明を入力してください。":"Enter a title and description for the custom preview.","SNSプレビューのタイトルまたは説明が長すぎます。":"The social preview title or description is too long.","プレビュー画像には公開HTTPS URLを入力してください。":"Enter a public HTTPS URL for the preview image.","入口の短縮パスを入力してください。":"Enter an entry short path.","入口のSNSプレビュー設定が正しくありません。":"The entry social preview setting is invalid.","親リンクの転送先からOG情報を取得できませんでした。":"Could not fetch preview data from the parent destination.","入口の指定プレビューには適切なタイトルと説明を入力してください。":"Enter a valid title and description for the entry preview.","入口のプレビュー画像には公開HTTPS URLを入力してください。":"Enter a public HTTPS URL for the entry preview image.","合言葉の変更と解除を同時には行えません。":"You cannot change and remove the passphrase at the same time.","入口は存在しません。":"This entry does not exist."};const translate=value=>{const trimmed=value.trim();let next=errors[trimmed]||trimmed;let match=/^利用回数の上限は([0-9,]+)回以下で入力してください。$/.exec(trimmed);if(match)next="The usage limit must be "+match[1]+" or fewer.";match=/^利用回数の上限は1以上の整数で入力してください。$/.exec(trimmed);if(match)next="The usage limit must be a whole number of at least 1.";match=/^終了後メッセージは(\\d+)文字以内にしてください。$/.exec(trimmed);if(match)next="The unavailable message must be "+match[1]+" characters or fewer.";match=/^入口ラベルは1〜(\\d+)文字で入力してください。$/.exec(trimmed);if(match)next="The entry label must contain 1 to "+match[1]+" characters.";const prefix=value.slice(0,value.indexOf(trimmed)),suffix=value.slice(value.indexOf(trimmed)+trimmed.length);return prefix+next+suffix};const convert=node=>{const parent=node.parentElement;if(!parent||parent.closest("[data-no-i18n]")||["SCRIPT","STYLE","TEXTAREA","OPTION"].includes(parent.tagName))return;const next=translate(node.nodeValue||"");if(next!==node.nodeValue)node.nodeValue=next};const scan=root=>{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(convert)};const formatTimes=()=>{const zone=Intl.DateTimeFormat().resolvedOptions().timeZone||"local";for(const element of document.querySelectorAll("[data-local-time]")){const date=new Date(element.dataset.localTime||"");if(!Number.isNaN(date.getTime())){const offset=new Intl.DateTimeFormat("en",{timeZoneName:"shortOffset"}).formatToParts(date).find(part=>part.type==="timeZoneName")?.value||"UTC";element.textContent=new Intl.DateTimeFormat("en",{dateStyle:"medium",timeStyle:"short"}).format(date)+" (Local time · "+zone+" / "+offset+")"}}};requestAnimationFrame(()=>{scan(document.body);formatTimes()});new MutationObserver(records=>{for(const record of records){if(record.type==="characterData")convert(record.target);else record.addedNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE)convert(node);else if(node instanceof Element)scan(node)})}}).observe(document.body,{subtree:true,childList:true,characterData:true})})();</script>`;
  const localizationCompletionScript = `<script>(()=>{if(document.documentElement.lang!=="en")return;const extra={"リンクの作成・管理にはCloudflare Turnstileによる確認が必要です。送信時にCloudflareのプライバシーポリシーと利用規約が適用されます。":"Creating and managing links requires Cloudflare Turnstile verification. Cloudflare's Privacy Policy and Terms of Service apply when you submit.","短縮URLを作成する前に、転送先URLを入力してください。":"Enter a destination URL before creating a short link.","相手別の入口を追加":"Add an audience entry","入口を更新する":"Update entry","期限: ":"Expires: ","親リンクの転送先ページからOG情報を取り込む":"Import preview from the parent destination","現在の親リンクの転送先URLを表示する":"Show the current parent destination URL","リンク設定が更新されました。もう一度開いてください。":"The link settings changed. Please open the link again.","相手別の入口を追加しました。":"Audience entry added.","入口を更新しました。":"Entry updated.","入口を削除しました。短縮パスは再利用できません。":"Entry deleted. Its short path cannot be reused.","この入口は存在しません。":"This entry does not exist."};const convert=node=>{const parent=node.parentElement;if(!parent||parent.closest("[data-no-i18n]")||["SCRIPT","STYLE","TEXTAREA","OPTION"].includes(parent.tagName))return;const value=node.nodeValue||"",trimmed=value.trim(),next=extra[trimmed];if(next)node.nodeValue=value.slice(0,value.indexOf(trimmed))+next+value.slice(value.indexOf(trimmed)+trimmed.length)};const scan=root=>{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(convert)};requestAnimationFrame(()=>scan(document.body));new MutationObserver(records=>{for(const record of records){if(record.type==="characterData")convert(record.target);else record.addedNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE)convert(node);else if(node instanceof Element)scan(node)})}}).observe(document.body,{subtree:true,childList:true,characterData:true})})();</script>`;
