function slugInput(name: string, value: string, id: string, placeholder = "未入力なら自動生成"): string { return `<div class="slug-input"><span>${escapeHtml(SERVICE_HOST)}/</span><input id="${id}" type="text" name="${name}" value="${escapeHtml(value)}" placeholder="${escapeHtml(placeholder)}" maxlength="64" pattern="[A-Za-z0-9_-]{1,64}" autocomplete="off" data-slug-check="#${id}_availability"></div><p id="${id}_availability" class="availability" aria-live="polite"></p>`; }
function copyField(label: string, value: string): string { return `<div class="copy-field"><label>${escapeHtml(label)}</label><div class="copy-row"><a href="${escapeHtml(value)}" rel="noreferrer">${escapeHtml(value)}</a><button type="button" class="copy-action" data-copy="${escapeHtml(value)}" data-copy-target="${escapeHtml(label)}" aria-label="${escapeHtml(`${label}をコピー`)}"><span data-copy-icon aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10.5 13.5a4.5 4.5 0 0 0 6.36.14l2.5-2.5a4.5 4.5 0 0 0-6.36-6.36l-1.43 1.42"></path><path d="M13.5 10.5a4.5 4.5 0 0 0-6.36-.14l-2.5 2.5A4.5 4.5 0 0 0 11 19.22l1.42-1.42"></path></svg></span><span data-copy-label>コピー</span></button><span class="copy-feedback" data-copy-feedback aria-live="polite" role="status"></span></div></div>`; }
function passphraseInput(id: string, autocomplete: string, required = false): string { return `<div class="secret-input"><input id="${escapeHtml(id)}" class="secret-field" type="password" name="passphrase"${required ? " required" : ""} autocomplete="${escapeHtml(autocomplete)}" maxlength="256"><button type="button" class="secondary secret-toggle" data-passphrase-toggle aria-controls="${escapeHtml(id)}" aria-pressed="false" aria-label="合言葉を表示"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"></path><circle cx="12" cy="12" r="2.5"></circle></svg></button></div>`; }
function renderLocalDateTime(value: string | null, empty = "なし"): string { const utcValue = utcDisplayValue(value); return utcValue ? `<time data-local-time="${escapeHtml(utcValue)}">${escapeHtml(utcValue)}（UTC）</time>` : escapeHtml(empty); }
function localDatetimeHint(id: string): string { return `<p class="hint" data-time-zone-for="${escapeHtml(id)}">入力・表示はお使いの端末の現地時間です。JavaScriptを無効にしている場合はUTCとして扱います。</p>`; }
function localDatetimeInput(id: string, name: string, value: string | null, includeHint = true): string { const utcValue = utcDisplayValue(value) ?? ""; const fallbackValue = utcValue ? utcValue.slice(0, 16) : ""; return `<input id="${escapeHtml(id)}" type="datetime-local" name="${escapeHtml(name)}" value="${escapeHtml(fallbackValue)}" data-local-datetime data-utc-value="${escapeHtml(utcValue)}">${includeHint ? localDatetimeHint(id) : `<p hidden data-time-zone-for="${escapeHtml(id)}"></p>`}`; }
function isScheduledTargetConfigured(scheduledTargetUrl: string | null, switchAt: string | null): boolean { return Boolean(scheduledTargetUrl && switchAt); }
function renderPreviewFields(link?: Link): string {
  const scheduleActive = isScheduledTargetConfigured(link?.scheduled_target_url ?? null, link?.switch_at ?? null);
  const mode = scheduleActive ? "none" : (link?.preview_mode ?? "none"); const disabled = scheduleActive ? " disabled" : "";
  return `<fieldset class="mode-picker" data-og-settings${disabled}><legend>SNSプレビュー（任意）</legend><p class="warning" data-og-disabled-notice ${scheduleActive ? "" : "hidden"}>転送先の切替を設定中は、切替前後で表示内容が変わるためSNSプレビューは利用できません。切替を解除すると設定できます。</p><label><input type="radio" name="preview_mode" value="none" ${mode === "none" ? "checked" : ""}><span>OGなし（既定）</span></label><label><input type="radio" name="preview_mode" value="target_og" ${mode === "target_og" ? "checked" : ""}><span>転送先ページからOG情報を取り込む</span></label><label><input type="radio" name="preview_mode" value="custom" ${mode === "custom" ? "checked" : ""}><span>タイトル・説明を指定する</span></label><label><input type="radio" name="preview_mode" value="target_url" ${mode === "target_url" ? "checked" : ""}><span>現在の転送先URLを表示する</span></label><p class="hint" data-og-mode-note>選択した方法でSNSプレビューを設定します。</p><div data-og-custom-fields ${mode === "custom" ? "" : "hidden"}><label for="og_title">プレビュータイトル</label><input id="og_title" type="text" name="og_title" value="${escapeHtml(link?.og_title ?? "")}" maxlength="${MAX_OG_TITLE_LENGTH}" autocomplete="off"><label for="og_description">プレビュー説明</label><textarea id="og_description" name="og_description" maxlength="${MAX_OG_DESCRIPTION_LENGTH}">${escapeHtml(link?.og_description ?? "")}</textarea><label for="og_image_url">プレビュー画像URL（任意）</label><input id="og_image_url" type="url" name="og_image_url" value="${escapeHtml(link?.og_image_url ?? "")}" maxlength="${MAX_OG_IMAGE_URL_LENGTH}" placeholder="https://example.com/image.jpg" autocomplete="url"></div><p class="hint">転送先の取り込みは保存時にHTTPSページへ1回だけアクセスします。画像は公開HTTPS URLのみ指定できます。説明には表示時にサービス名を付記します。</p></fieldset>`;
}
function renderExpiryFields(link?: Link, createForm = false): string {
  const title = createForm ? "有効期限（任意）" : "共有期限（任意）";
  const label = createForm ? "有効期限" : "共有期限";
  return `<fieldset class="mode-picker"><legend>${title}</legend><label for="expires_at">${label}</label>${localDatetimeInput("expires_at", "expires_at", link?.expires_at ?? null, !createForm)}<p class="hint">指定時刻を過ぎると、このリンクは利用できなくなります。</p></fieldset>`;
}
function renderTerminalMessageFields(link?: Link, createForm = false): string {
  const title = createForm ? "リンク終了時の表示（任意）" : "利用できなくなった時のメッセージ（任意）";
  const label = createForm ? "終了メッセージ" : "終了後に表示するメッセージ";
  return `<fieldset class="mode-picker"><legend>${title}</legend><label for="ended_message">${label}</label><textarea id="ended_message" name="ended_message" maxlength="${MAX_INVITATION_ENDED_MESSAGE_LENGTH}">${escapeHtml(link?.ended_message ?? "")}</textarea><p class="hint">共有期限切れや利用回数の上限到達後に表示します。未入力なら既定のメッセージを表示します。</p></fieldset>`;
}
function renderInitialAudienceFields(): string {
  const fields = renderAudienceFields().replace(' required maxlength', ' maxlength');
  return `<details class="advanced"><summary>最初の相手別の入口を追加（任意）</summary><p class="hint">作成と同時に、相手・用途別の入口URLを1つだけ作れます。入口を設定する場合は、ラベルと短縮パスを入力してください。追加の入口は作成後の管理画面で設定できます。</p>${fields}</details>`;
}
function renderCreateDetails(): string {
  const icon = (path: string) => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"></path></svg>`;
  const card = (id: string, kind: string, title: string, description: string, iconPath: string, body: string) => `<section id="${id}" class="condition-card" data-condition-card="${kind}"><div class="condition-card-header"><span class="condition-card-icon">${icon(iconPath)}</span><label class="condition-card-title" for="${kind}_enabled"><strong>${title}</strong><span>${description}</span></label><label class="condition-switch"><input id="${kind}_enabled" type="checkbox" data-condition-toggle aria-controls="${kind}_fields"><span aria-hidden="true"></span></label></div><div id="${kind}_fields" class="condition-card-body" data-condition-body hidden>${body}</div></section>`;
  const period = card("create-condition-expiry", "period", "利用できる期間", "指定した期間のみ有効", "M7 2v4m10-4v4M3 10h18M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z", `<div class="condition-card-grid"><div class="condition-card-field"><label for="unlock_at">開始日時</label>${localDatetimeInput("unlock_at", "unlock_at", null, false)}</div><div class="condition-card-field"><label for="expires_at">終了日時</label>${localDatetimeInput("expires_at", "expires_at", null, false)}</div></div><p class="hint">どちらか一方だけでも設定できます。終了後は下記の「終了時の表示」が適用されます。</p>`);
  const usage = card("create-condition-limit", "limit", "回数制限", "アクセスできる回数の上限", "M20 11a8 8 0 0 0-14.9-4M4 4v4h4m-4 5a8 8 0 0 0 14.9 4M20 20v-4h-4", `<div class="condition-card-grid"><div class="condition-card-field"><label for="max_open_count">上限回数</label><input id="max_open_count" type="number" name="max_open_count" min="1" max="${MAX_OPEN_COUNT}" step="1" inputmode="numeric" placeholder="例: 1,000"><p class="hint">通常アクセスのみ数えます。SNSプレビューは数えません。</p></div><div class="condition-card-field"><label for="limit_reached_action">上限到達後の動作</label><select id="limit_reached_action" class="condition-card-select" data-limit-reached-action><option value="end">リンクを終了（終了メッセージを表示）</option><option value="redirect">別のURLへ転送</option></select></div><div id="limit_reached_target_fields" data-limit-fallback-fields hidden><input id="limit_reached_target_enabled" class="condition-contract-checkbox" type="checkbox" name="limit_reached_target_enabled" value="1" tabindex="-1" aria-hidden="true"><label for="limit_reached_target_url">転送先URL</label><input id="limit_reached_target_url" type="url" name="limit_reached_target_url" placeholder="https://example.com/after-limit" maxlength="2048" autocomplete="url"></div></div>`);
  const redirects = card("create-condition-schedule", "schedule", "日時で転送先を変更", "指定日時以降に別URLへ転送", "M19 8v6h-6m3.3 3.3A8 8 0 1 1 19 8", `<div class="condition-card-grid"><div class="condition-card-field"><label for="switch_at">切替日時</label>${localDatetimeInput("switch_at", "switch_at", null, false)}</div><div class="condition-card-field"><label for="scheduled_target_url">切替後の転送先URL</label><input id="scheduled_target_url" type="url" name="scheduled_target_url" placeholder="https://example.com/new" maxlength="2048" autocomplete="url"></div></div><p class="hint">日時と転送先URLの両方を入力してください。</p>`);
  const protection = card("create-condition-protection", "protection", "合言葉で保護", "合言葉を入力した人だけに公開", "M5 11h14v10H5zM8 11V8a4 4 0 0 1 8 0v3", `<div class="condition-card-field"><label for="passphrase">合言葉</label>${passphraseInput("passphrase", "new-password")}<p class="hint">データベースには安全にハッシュ化して保存されます。</p></div>`);
  const endDisplay = card("create-condition-end-display", "end-display", "終了時の表示", "リンクを利用できなくなったときの案内", "M12 9v4m0 4h.01M10 3h4l7 7-7 7h-4l-7-7 7-7Z", renderTerminalMessageFields(undefined, true));
  const preview = card("create-condition-preview", "preview", "表示設定", "SNSで共有したときのプレビュー", "M2 12s3.5-6 10-6 10 6-3.5 6-10 6S2 12 2 12Zm10 3a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z", renderPreviewFields());
  const audience = card("create-condition-audience", "audience", "最初の相手別入口", "相手・用途別の入口URLを同時に作成", "M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m13-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm6 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75", renderInitialAudienceFields());
  return `<details class="advanced create-details"><summary><span>詳細設定</span><span data-detail-summary-description>SNSプレビュー・終了時表示・相手別入口</span><svg class="create-details-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"></path></svg></summary><div class="detail-content">${localDatetimeHint("create-details")}${period}${usage}${redirects}${protection}${endDisplay}${preview}${audience}</div></details>`;
}
function renderHome(_request: Request, env: Env, error?: string): Response {
  const turnstile = env.TURNSTILE_SITE_KEY ? `<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script><div class="cf-turnstile" data-sitekey="${escapeHtml(env.TURNSTILE_SITE_KEY)}" data-action="${TURNSTILE_ACTION}"></div>` : "";
  const templates = `<style>.create-studio .condition-card:target{border-color:#d65248;box-shadow:0 0 0 2px rgba(214,82,72,.18)}.create-studio input:target,.create-studio textarea:target,.create-studio select:target{border-color:#d65248;box-shadow:0 0 0 2px rgba(214,82,72,.18)}.create-studio [data-rule-conditions][hidden],.create-studio [data-rule-condition][hidden]{display:none!important}</style>`;
  const rules = `<section class="rule-preview" aria-live="polite"><style>.create-studio .rule-preview{display:grid;align-content:start;gap:16px}.create-studio .rule-preview>h2{font-size:1.06rem}.create-studio .rule-preview>p{margin:0;color:#b8b2aa;font-size:.9rem;line-height:1.65}.create-studio .rule-current{display:grid;gap:14px;padding:22px;border:1px solid #5b4938;border-radius:10px;background:#171816}.create-studio .rule-current .eyebrow{margin:0;color:#c8c2b9;font-size:.78rem}.create-studio .rule-current-outcome{display:grid;grid-template-columns:58px minmax(0,1fr);align-items:center;gap:16px}.create-studio .rule-current-arrow{display:grid;place-items:center;width:54px;height:54px;border:2px solid #f58209;border-radius:50%;color:#f58209;font-size:2.25rem;line-height:1}.create-studio .rule-current strong{display:block;color:#f3f1ed;font-size:clamp(1.35rem,2.2vw,1.85rem);line-height:1.2}.create-studio .rule-current.is-ready strong{color:#f39a14}.create-studio .rule-current p:not(.eyebrow){margin:8px 0 0;color:#c8c2b9;font-size:.9rem;line-height:1.55;overflow-wrap:anywhere}.create-studio .rule-conditions{display:grid;gap:10px}.create-studio .rule-conditions>h3{margin:0;font-size:1.02rem}.create-studio .rule-conditions>p{margin:0;color:#b8b2aa;font-size:.88rem;line-height:1.55}.create-studio .rule-conditions ol{position:relative;display:grid;gap:0;margin:2px 0 0;padding:0;list-style:none;border:1px solid #3c3a35;border-radius:10px;background:#171816;overflow:hidden}.create-studio .rule-conditions li{display:grid;grid-template-columns:42px minmax(0,1fr);gap:14px;align-items:center;min-height:72px;margin:0;padding:14px 16px;border:0;border-bottom:1px solid #393732;border-radius:0;background:transparent}.create-studio .rule-conditions li:last-child{border-bottom:0}.create-studio .rule-conditions li>b{width:34px;height:34px;border:1px solid #6a6056;border-radius:50%;background:#242421;color:#e7d6bf;font-size:1rem}.create-studio .rule-conditions li div{display:grid;gap:4px}.create-studio .rule-conditions li strong{font-size:1rem}.create-studio .rule-conditions li span{color:#c8c2b9;font-size:.88rem;line-height:1.45;overflow-wrap:anywhere}.create-studio .rule-note{padding:0!important;background:transparent!important;color:#aaa69e!important;font-size:.84rem!important}@media(max-width:560px){.create-studio .rule-current{padding:18px}.create-studio .rule-current-outcome{grid-template-columns:46px minmax(0,1fr);gap:12px}.create-studio .rule-current-arrow{width:44px;height:44px;font-size:1.8rem}.create-studio .rule-current strong{font-size:1.25rem}.create-studio .rule-conditions li{grid-template-columns:34px minmax(0,1fr);gap:10px;padding:13px}.create-studio .rule-conditions li>b{width:30px;height:30px}}</style><h2>動作ルール</h2><p>このリンクがクリックされたときの動作を設定できます。</p><section class="rule-current" data-rule-current><p class="eyebrow">現在の動作</p><div class="rule-current-outcome"><span class="rule-current-arrow" aria-hidden="true">→</span><div><strong data-rule-current-title>転送先URLを入力してください</strong><p data-rule-default>転送先URLを入力すると、ここに現在の動作を表示します。</p></div></div></section><section class="rule-conditions" data-rule-conditions hidden><h3>動作を変える条件</h3><p>条件が一致した場合だけ、上から順に優先されます。</p><ol><li data-rule-condition="expiry" hidden><b>1</b><div><strong>有効期限</strong><span data-rule-expiry></span></div></li><li data-rule-condition="access" hidden><b>2</b><div><strong>利用開始・合言葉</strong><span data-rule-access></span></div></li><li data-rule-condition="limit" hidden><b>3</b><div><strong>回数制限</strong><span data-rule-limit></span></div></li><li data-rule-condition="schedule" hidden><b>4</b><div><strong>日時による切替</strong><span data-rule-schedule></span></div></li></ol></section><p class="rule-note">設定済みの条件だけを表示します。条件は上から順に判定されます。</p></section>`;
  return renderLayout("短縮URLを作成", `<section class="create-studio"><div class="create-pane"><h1>短縮URLを作成</h1><p class="lead">共有の条件やタイミングを設定して、短縮URLを作成します。</p>${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}<form class="create-form" method="POST" action="/create">${templates}<section class="create-basics"><label for="target_url">最初の転送先URL</label><input id="target_url" type="url" name="target_url" placeholder="https://example.com/a" required maxlength="2048" autocomplete="url"><label for="custom_slug">短縮パス</label>${slugInput("custom_slug", "", "custom_slug")}<p class="hint">英数字、ハイフン、アンダースコア。未入力なら自動生成します。</p></section>${renderCreateDetails()}<section class="short-url"><h2>作成される短縮URL</h2><output data-preview-short-url>${SERVICE_HOST}/…</output><p class="validation" data-create-validation>転送先URLと短縮パスを確認してください</p></section>${turnstile}<button type="submit" data-create-submit>短縮URLを作成</button></form></div><aside class="preview-pane"><h2>プレビューと動作</h2><article class="share-preview"><img src="/assets/share-preview-amber-waves.jpg" alt="オレンジ色の波模様"><div><h3 data-preview-og-title>美しい共有体験を、かんたんに</h3><p data-preview-og-description>リンクの共有をもっとスマートに。時間・回数・期限などの条件付きで安全にリンクを届けられます。</p><small data-preview-og-host>go.snkisk.com</small></div></article>${rules}<p class="note">アクセス履歴・IPアドレス・User-Agentは保存しません。利用回数制限を設定した場合のみ、累計利用回数を保持します。</p></aside></section>`, 200, Boolean(env.TURNSTILE_SITE_KEY));
}
function renderCreatedPage(shortUrl: string, manageUrl: string, link: Link): Response {
  return renderLayout("短縮URLを作成しました", `<section class="card"><h1>短縮URLを作成しました</h1>${copyField("短縮URL", shortUrl)}<div class="qr">${qrImage(shortUrl)}</div>${copyField("管理URL", manageUrl)}${renderLinkMeta(link)}<p class="warning">管理URLを知っている人はリンクを編集・削除できます。公開しないでください。</p><p><a class="button secondary" href="/">トップに戻る</a></p></section>`);
}
function renderLinkMeta(link: Link): string { const scheduleActive = isScheduledTargetConfigured(link.scheduled_target_url, link.switch_at); const switchText = scheduleActive ? `${renderLocalDateTime(link.switch_at)} から切替` : "なし"; const previewText = scheduleActive ? "切替設定中のため無効" : link.preview_mode; const openLimitText = link.max_open_count === null ? "無制限" : `${link.max_open_count}回まで（${link.open_count}回使用済み）`; const limitReachedText = link.limit_reached_target_url ? "設定済み" : "なし"; return `<dl class="meta"><div><dt>利用回数</dt><dd data-open-limit>${escapeHtml(openLimitText)}</dd></div><div><dt>上限到達後の転送</dt><dd>${escapeHtml(limitReachedText)}</dd></div><div><dt>公開開始</dt><dd>${renderLocalDateTime(link.unlock_at, "すぐに公開")}</dd></div><div><dt>転送先切替</dt><dd>${switchText}</dd></div><div><dt>合言葉</dt><dd>${link.passphrase_hash ? "設定済み" : "なし"}</dd></div><div><dt>SNSプレビュー</dt><dd>${escapeHtml(previewText)}</dd></div></dl>`; }
function renderAudienceFields(entry?: AudienceEntry, idSuffix = "new", scheduleActive = false): string {
  const mode = scheduleActive ? "none" : (entry?.preview_mode ?? "none"); const disabled = scheduleActive ? " disabled" : "";
  const basics = `<label for="entry_label_${idSuffix}">入口ラベル</label><input id="entry_label_${idSuffix}" type="text" name="entry_label" value="${escapeHtml(entry?.label ?? "")}" required maxlength="${MAX_AUDIENCE_LABEL_LENGTH}" placeholder="例: 友達用・QR用"><label for="entry_slug_${idSuffix}">入口の短縮パス</label>${slugInput("entry_slug", entry?.slug ?? "", `entry_slug_${idSuffix}`, "入口の短縮パス（必須）")}`;
  const expiry = `<fieldset class="mode-picker"><legend>入口の共有期限（任意）</legend><label for="entry_expires_at_${idSuffix}">共有期限</label>${localDatetimeInput(`entry_expires_at_${idSuffix}`, "entry_expires_at", entry?.expires_at ?? null)}<p class="hint">指定時刻を過ぎると、この入口は利用できなくなります。</p></fieldset>`;
  const terminalMessage = `<fieldset class="mode-picker"><legend>入口が利用できなくなった時のメッセージ（任意）</legend><label for="entry_ended_message_${idSuffix}">終了後に表示するメッセージ</label><textarea id="entry_ended_message_${idSuffix}" name="entry_ended_message" maxlength="${MAX_INVITATION_ENDED_MESSAGE_LENGTH}">${escapeHtml(entry?.ended_message ?? "")}</textarea><p class="hint">入口の期限切れや、親リンクの利用回数上限到達後に表示します。未入力なら親リンクのメッセージまたは既定文を表示します。</p></fieldset>`;
  const preview = `<fieldset class="mode-picker" data-og-settings${disabled}><legend>入口ごとのSNSプレビュー（任意）</legend><p class="warning" data-og-disabled-notice ${scheduleActive ? "" : "hidden"}>転送先の切替を設定中は、切替前後で表示内容が変わるためSNSプレビューは利用できません。切替を解除すると設定できます。</p><label><input type="radio" name="entry_preview_mode" value="none" ${mode === "none" ? "checked" : ""}><span>OGなし（既定）</span></label><label><input type="radio" name="entry_preview_mode" value="target_og" ${mode === "target_og" ? "checked" : ""}><span>親リンクの転送先ページからOG情報を取り込む</span></label><label><input type="radio" name="entry_preview_mode" value="custom" ${mode === "custom" ? "checked" : ""}><span>タイトル・説明を指定する</span></label><label><input type="radio" name="entry_preview_mode" value="target_url" ${mode === "target_url" ? "checked" : ""}><span>現在の親リンクの転送先URLを表示する</span></label><div data-og-custom-fields ${mode === "custom" ? "" : "hidden"}><label for="entry_og_title_${idSuffix}">プレビュータイトル</label><input id="entry_og_title_${idSuffix}" type="text" name="entry_og_title" value="${escapeHtml(entry?.og_title ?? "")}" maxlength="${MAX_OG_TITLE_LENGTH}"><label for="entry_og_description_${idSuffix}">プレビュー説明</label><textarea id="entry_og_description_${idSuffix}" name="entry_og_description" maxlength="${MAX_OG_DESCRIPTION_LENGTH}">${escapeHtml(entry?.og_description ?? "")}</textarea><label for="entry_og_image_url_${idSuffix}">プレビュー画像URL（任意）</label><input id="entry_og_image_url_${idSuffix}" type="url" name="entry_og_image_url" value="${escapeHtml(entry?.og_image_url ?? "")}" maxlength="${MAX_OG_IMAGE_URL_LENGTH}" placeholder="https://example.com/image.jpg"></div></fieldset>`;
  return `${basics}${expiry}${terminalMessage}${preview}`;
}
function renderAudienceEntries(link: Link, entries: AudienceEntry[], origin: string): string {
  const scheduleActive = isScheduledTargetConfigured(link.scheduled_target_url, link.switch_at);
  const create = `<details><summary>相手別の入口を追加</summary><form method="POST" action="/manage/${escapeHtml(link.slug)}/entries/create"><input type="hidden" name="key" value="${escapeHtml(link.manage_key)}">${renderAudienceFields(undefined, "new", scheduleActive)}<button type="submit">入口を追加する</button></form></details>`;
  const rows = entries.length ? entries.map((entry) => `<details><summary>${escapeUserTextForI18n(entry.label)} — ${escapeHtml(entry.slug)}${entry.expires_at ? `（期限: ${renderLocalDateTime(entry.expires_at)}）` : ""}${scheduleActive ? "（SNSプレビュー無効）" : ""}</summary>${copyField("入口URL", `${origin}/${entry.slug}`)}<form method="POST" action="/manage/${escapeHtml(link.slug)}/entries/${entry.id}"><input type="hidden" name="key" value="${escapeHtml(link.manage_key)}">${renderAudienceFields(entry, String(entry.id), scheduleActive)}<button type="submit">入口を更新する</button></form><form method="POST" action="/manage/${escapeHtml(link.slug)}/entries/${entry.id}/delete"><input type="hidden" name="key" value="${escapeHtml(link.manage_key)}"><button type="submit" class="danger">この入口を削除する</button></form></details>`).join("") : "<p class=\"hint\">まだ入口はありません。</p>";
  return `<section class="card"><h2>相手別の入口URL</h2><p class="hint">入口ごとに期限・終了メッセージ・SNSプレビューを変えられます。転送先、公開開始、利用回数の上限、合言葉は親リンクの設定を共有します。</p>${rows}${create}</section>`;
}
async function renderManagePage(env: Env, link: Link, shortUrl: string, manageUrl: string, message?: string): Promise<Response> {
  const usage = link.max_open_count === null ? "無制限" : `${link.open_count} / ${link.max_open_count} 回使用済み`;
  const usageUrl = link.max_open_count === null ? "" : `/api/manage/${encodeURIComponent(link.slug)}/usage?key=${encodeURIComponent(link.manage_key)}`;
  const summary = `<dl class="meta"><div><dt>現在の転送先</dt><dd><a href="${escapeHtml(link.target_url)}" rel="noreferrer">${escapeHtml(link.target_url)}</a></dd></div><div><dt>利用状況</dt><dd id="usage_count" data-usage-url="${escapeHtml(usageUrl)}" aria-live="polite">${escapeHtml(usage)}</dd></div><div><dt>作成日時</dt><dd>${renderLocalDateTime(link.created_at)}</dd></div></dl>${renderLinkMeta(link)}`;
  const form = `<form method="POST" action="/manage/${escapeHtml(link.slug)}"><input type="hidden" name="key" value="${escapeHtml(link.manage_key)}"><label for="target_url">現在の転送先URL</label><input id="target_url" type="url" name="target_url" value="${escapeHtml(link.target_url)}" required maxlength="2048"><label for="slug">短縮パス</label>${slugInput("slug", link.slug, "slug")}<fieldset class="mode-picker"><legend>利用回数の上限（任意）</legend><label for="max_open_count">利用回数の上限</label><input id="max_open_count" type="number" name="max_open_count" value="${link.max_open_count ?? ""}" min="1" max="${MAX_OPEN_COUNT}" step="1" inputmode="numeric" placeholder="未入力なら無制限"><p class="hint">通常アクセスの回数を数えます。SNSプレビューは数えません。親URLと相手別入口の合計で消費します。更新すると利用回数は0に戻ります。</p><label class="check"><input id="limit_reached_target_enabled" type="checkbox" name="limit_reached_target_enabled" value="1" data-limit-fallback-toggle="#limit_reached_target_url" ${link.limit_reached_target_url ? "checked" : ""}><span>上限到達後に別のURLへ転送する</span></label><label for="limit_reached_target_url">上限到達後の転送先URL</label><input id="limit_reached_target_url" type="url" name="limit_reached_target_url" value="${escapeHtml(link.limit_reached_target_url ?? "")}" placeholder="https://example.com/after-limit" maxlength="2048" autocomplete="url"><p class="hint">オンにすると、上限到達後の通常アクセスをこのURLへ転送します。オフなら終了メッセージを表示します。</p></fieldset><fieldset class="mode-picker"><legend>公開時の条件</legend><label for="scheduled_target_url">切替後の転送先URL</label><input id="scheduled_target_url" type="url" name="scheduled_target_url" value="${escapeHtml(link.scheduled_target_url ?? "")}" placeholder="設定しない" maxlength="2048"><label for="switch_at">切替日時</label>${localDatetimeInput("switch_at", "switch_at", link.switch_at)}<label for="unlock_at">公開開始日時</label>${localDatetimeInput("unlock_at", "unlock_at", link.unlock_at)}<label for="passphrase">新しい合言葉</label>${passphraseInput("passphrase", "new-password")}<label class="check"><input type="checkbox" name="clear_passphrase" value="1"><span>現在の合言葉を解除する</span></label><p class="hint">空欄なら現在の合言葉を維持します。合言葉は表示・復元できません。</p></fieldset>${renderExpiryFields(link)}${renderTerminalMessageFields(link)}${renderPreviewFields(link)}<p class="hint">更新すると利用回数はリセットされます。</p><button type="submit">更新する</button></form>`;
  const entries = await getAudienceEntries(env, link.id);
  return renderLayout("管理画面", `<section class="card"><p class="eyebrow">管理画面</p><h1>リンクを管理</h1>${message ? `<p class="success">${escapeHtml(message)}</p>` : ""}${copyField("短縮URL", shortUrl)}<div class="qr">${qrImage(shortUrl)}</div>${copyField("管理URL", manageUrl)}${summary}${form}<form method="POST" action="/delete/${escapeHtml(link.slug)}"><input type="hidden" name="key" value="${escapeHtml(link.manage_key)}"><button type="submit" class="danger">削除する</button></form></section>${renderAudienceEntries(link, entries, new URL(shortUrl).origin)}`);
}
function renderPassphrasePage(target: PublicTarget, error?: string): Response { return renderLayout("合言葉が必要です", `<section class="card"><h1>合言葉が必要です</h1><p class="lead">このリンクを開くには、共有者から受け取った合言葉を入力してください。</p>${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}<form method="POST" action="/unlock/${escapeHtml(target.slug)}"><label for="passphrase">合言葉</label>${passphraseInput("passphrase", "current-password", true)}<button type="submit">確認する</button></form></section>`); }
function renderTerminalUnavailable(endedMessage: string | null): Response { const message = endedMessage ?? "このリンクは利用できなくなりました。"; return renderLayout("このリンクは利用できません", `<section class="card"><h1>このリンクは利用できません</h1><p class="lead"${endedMessage ? " data-no-i18n" : ""}>${endedMessage ? escapeUserTextForI18n(message) : escapeHtml(message)}</p></section>`); }
function renderLockedPage(unlockAt: string): Response {
  const unlockAtMs = Date.parse(unlockAt);
  return renderLayout("まだ開けません", `<section class="card"><h1>まだ開けません</h1><p class="lead">このリンクは ${renderLocalDateTime(unlockAt)} から開けます。</p><label class="check"><input id="open_when_unlocked" type="checkbox" data-unlock-at-ms="${Number.isFinite(unlockAtMs) ? unlockAtMs : ""}"><span>公開時刻になったらリンクを開く</span></label><p id="open_when_unlocked_status" class="hint" aria-live="polite"></p><p class="hint">このページを開いたままにしている間だけ自動で開きます。</p><script>(()=>{const checkbox=document.querySelector("#open_when_unlocked"),status=document.querySelector("#open_when_unlocked_status");if(!(checkbox instanceof HTMLInputElement)||!status)return;const unlockAtMs=Number(checkbox.dataset.unlockAtMs);let timer;const schedule=()=>{clearTimeout(timer);if(!checkbox.checked){status.textContent="";return}const remaining=unlockAtMs-Date.now();if(!Number.isFinite(remaining)){status.textContent="公開時刻を確認できません。";return}if(remaining<=0){window.location.replace(window.location.href);return}status.textContent="公開時刻になったら自動的に開きます。";timer=window.setTimeout(schedule,Math.min(remaining,60000))};checkbox.addEventListener("change",schedule)})();</script></section>`, 423);
}
function renderDeletedPage(): Response { return renderLayout("削除しました", `<section class="card"><h1>削除しました</h1><p>短縮URLは削除されました。以後、このURLへアクセスすると404になります。</p><p><a class="button secondary" href="/">トップに戻る</a></p></section>`); }
function renderErrorPage(status: number, title: string, message: string, allow?: string): Response { const response = renderLayout(title, `<section class="card"><h1>${status}</h1><p class="lead">${escapeHtml(message)}</p><p><a class="button secondary" href="/">トップに戻る</a></p></section>`, status); if (allow) response.headers.set("Allow", allow); return response; }
function createErrorFocus(message: string): string { if (message.includes("OG情報") || message.includes("SNSプレビュー") || message.includes("指定プレビュー") || message.includes("プレビュー画像")) return "create-condition-preview"; if (message.includes("短縮パス")) return "custom_slug"; if (message.includes("利用回数") || message.includes("上限到達後")) return "create-condition-limit"; if (message.includes("切替")) return "create-condition-schedule"; if (message.includes("開始日時") || message.includes("共有期限")) return "create-condition-expiry"; if (message.includes("合言葉")) return "create-condition-protection"; if (message.includes("入口")) return "create-condition-audience"; return "target_url"; }
function renderCreateErrorPage(message: string, focus = createErrorFocus(message)): Response { const query = new URLSearchParams({ restore: "1", error: message, focus }); const hash = focus ? `#${encodeURIComponent(focus)}` : ""; return renderLayout("設定を変更", `<section class="card"><h1>設定を確認してください</h1><div class="error" role="alert"><strong>作成できませんでした</strong><p>${escapeHtml(message)}</p></div><p class="hint">入力済みの設定は保持されています。内容を確認してから、もう一度作成してください。</p><p><a class="button secondary" href="/?${query.toString()}${hash}">設定を変更</a></p></section>`, 400); }

function isPreviewRequest(request: Request): boolean {
  if (new URL(request.url).searchParams.get("preview") === "og") return true;
  const purpose = `${request.headers.get("Purpose") ?? ""} ${request.headers.get("Sec-Purpose") ?? ""} ${request.headers.get("X-Purpose") ?? ""}`;
  if (/preview|prefetch|prerender/i.test(purpose)) return true;
  const userAgent = request.headers.get("User-Agent") ?? "";
  return /facebookexternalhit|facebot|twitterbot|linkedinbot|slackbot|discordbot|telegrambot|whatsapp|pinterestbot|redditbot|googlebot|google-pagerenderer|googledocs|bingbot|applebot|skypeuripreview|msteams|microsoft\s+teams/i.test(userAgent);
}
function appendOgAttribution(description: string): string { return `${description}\n\n${OG_ATTRIBUTION}`; }
function renderPreviewUnavailable(): Response {
  const description = appendOgAttribution("この短縮リンクは現在プレビューを表示できません。");
  return htmlResponse(`<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(OG_SITE_NAME)}</title><meta property="og:type" content="website"><meta property="og:site_name" content="${escapeHtml(OG_SITE_NAME)}"><meta property="og:description" content="${escapeHtml(description)}"><meta name="twitter:card" content="summary"><meta name="twitter:description" content="${escapeHtml(description)}"></head><body><p>${escapeHtml(OG_SITE_NAME)}</p><p>${escapeHtml(description)}</p></body></html>`);
}
function renderOgPreview(request: Request, target: PublicTarget): Response {
  const { link, entry, slug } = target; const previewMode = entry?.preview_mode ?? link.preview_mode;
  const destination = activeDestination(link);
  const snapshot = previewMode === "target_url"
    ? { title: `リンク先: ${destination}`, description: destination, imageUrl: null }
    : entry ? { title: entry.og_title, description: entry.og_description, imageUrl: entry.og_image_url } : { title: link.og_title, description: link.og_description, imageUrl: link.og_image_url };
  const title = snapshot.title || "短縮リンク";
  const description = appendOgAttribution(snapshot.description || "この短縮リンクの転送先を開きます。");
  const image = snapshot.imageUrl ? `<meta property="og:image" content="${escapeHtml(snapshot.imageUrl)}"><meta name="twitter:image" content="${escapeHtml(snapshot.imageUrl)}">` : "";
  const shortUrl = buildShortUrl(request, slug);
  return htmlResponse(`<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(title)}</title><meta property="og:type" content="website"><meta property="og:url" content="${escapeHtml(shortUrl)}"><meta property="og:site_name" content="${escapeHtml(OG_SITE_NAME)}"><meta property="og:title" content="${escapeHtml(title)}"><meta property="og:description" content="${escapeHtml(description)}"><meta name="twitter:card" content="${snapshot.imageUrl ? "summary_large_image" : "summary"}"><meta name="twitter:title" content="${escapeHtml(title)}"><meta name="twitter:description" content="${escapeHtml(description)}">${image}</head><body><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p><p>${escapeHtml(OG_SITE_NAME)}</p></body></html>`);
}

async function verifyTurnstile(token: string | null, request: Request, env: Env): Promise<boolean> {
  if (!env.TURNSTILE_SECRET_KEY || !token) return false;
  const body = new URLSearchParams({ secret: env.TURNSTILE_SECRET_KEY, response: token }); const remoteIp = request.headers.get("CF-Connecting-IP"); if (remoteIp) body.set("remoteip", remoteIp);
  try { const response = await fetch(TURNSTILE_VERIFY_URL, { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body }); if (!response.ok) return false; const result = await response.json() as TurnstileVerifyResponse; const host = new URL(request.url).hostname.toLowerCase(); const expectedHost = host === "localhost" || host === "127.0.0.1" ? host : SERVICE_HOST; return result.success === true && result.hostname?.toLowerCase() === expectedHost && result.action === TURNSTILE_ACTION; } catch { return false; }
}
async function createPassphraseRecord(passphrase: string): Promise<PassphraseRecord> { const salt = crypto.getRandomValues(new Uint8Array(16)); const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(passphrase), "PBKDF2", false, ["deriveBits"]); const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: PASSPHRASE_ITERATIONS }, key, 256); return { salt: base64UrlEncode(salt), hash: base64UrlEncode(new Uint8Array(bits)), iterations: PASSPHRASE_ITERATIONS }; }
async function matchesPassphrase(link: Link, passphrase: string): Promise<boolean> { if (!link.passphrase_hash || !link.passphrase_salt || !link.passphrase_iterations) return false; const salt = base64UrlDecode(link.passphrase_salt); const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(passphrase), "PBKDF2", false, ["deriveBits"]); const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: link.passphrase_iterations }, key, 256); return timingSafeStringEqual(base64UrlEncode(new Uint8Array(bits)), link.passphrase_hash); }
async function createLink(env: Env, values: CreateValues, initialAudience: AudienceValues | null): Promise<Link> {
  const manageKey = generateManageKey();
  const insert = async (slug: string): Promise<Link> => {
    if (initialAudience) {
      await env.DB.batch([
        linkInsertStatement(env, slug, manageKey, values),
        env.DB.prepare(`INSERT INTO audience_entries (parent_link_id,slug,label,expires_at,ended_message,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url) SELECT id,?,?,?,?,?,?,?,?,?,?,? FROM links WHERE slug=? AND manage_key=? AND deleted_at IS NULL`).bind(initialAudience.slug, initialAudience.label, initialAudience.expiresAt, initialAudience.endedMessage, initialAudience.shareCardEnabled ? 1 : 0, initialAudience.shareCardTitle, initialAudience.shareCardDescription, initialAudience.previewMode, initialAudience.ogTitle, initialAudience.ogDescription, initialAudience.ogImageUrl, slug, manageKey),
      ]);
    } else {
      await linkInsertStatement(env, slug, manageKey, values).run();
    }
    const created = await getLinkBySlug(env, slug); if (!created) throw new Error("Created link was not found"); return created;
  };
  if (values.slug) {
    try { return await insert(values.slug); } catch (error) { if (isUniqueConstraintError(error)) throw new SlugUnavailableError(); throw error; }
  }
  for (let attempt = 0; attempt < MAX_SLUG_ATTEMPTS; attempt += 1) {
    const slug = generateSlug();
    try { return await insert(slug); } catch (error) {
      if (!isUniqueConstraintError(error)) throw error;
      if (initialAudience && await isIssuedSlug(env, initialAudience.slug)) throw new SlugUnavailableError();
    }
  }
  throw new SlugUnavailableError();
}
interface CreateValues { slug?: string; targetUrl: string; maxOpenCount: number | null; limitReachedTargetUrl: string | null; scheduledTargetUrl: string | null; switchAt: string | null; unlockAt: string | null; expiresAt: string | null; endedMessage: string | null; receiptRequired: boolean; passphrase: PassphraseRecord | null; shareCardEnabled: boolean; shareCardTitle: string | null; shareCardDescription: string | null; previewMode?: PreviewMode; ogTitle?: string | null; ogDescription?: string | null; ogImageUrl?: string | null; }
function linkInsertStatement(env: Env, slug: string, manageKey: string, values: CreateValues): D1PreparedStatement { return env.DB.prepare(`INSERT INTO links (slug,target_url,manage_key,one_time,max_open_count,open_count,limit_reached_target_url,scheduled_target_url,switch_at,unlock_at,expires_at,ended_message,receipt_required,passphrase_salt,passphrase_hash,passphrase_iterations,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(slug, values.targetUrl, manageKey, values.maxOpenCount === 1 ? 1 : 0, values.maxOpenCount, 0, values.limitReachedTargetUrl, values.scheduledTargetUrl, values.switchAt, values.unlockAt, values.expiresAt, values.endedMessage, values.receiptRequired ? 1 : 0, values.passphrase?.salt ?? null, values.passphrase?.hash ?? null, values.passphrase?.iterations ?? null, values.shareCardEnabled ? 1 : 0, values.shareCardTitle, values.shareCardDescription, values.previewMode ?? "none", values.ogTitle ?? null, values.ogDescription ?? null, values.ogImageUrl ?? null); }
async function isIssuedSlug(env: Env, slug: string): Promise<boolean> { return Boolean(await env.DB.prepare("SELECT 1 FROM issued_slugs WHERE slug=? LIMIT 1").bind(slug).first()); }
async function getLinkBySlug(env: Env, slug: string): Promise<Link | null> { return env.DB.prepare(`SELECT id,slug,target_url,manage_key,one_time,used_at,max_open_count,open_count,limit_reached_target_url,scheduled_target_url,switch_at,unlock_at,expires_at,ended_message,receipt_required,receipt_confirmed_at,passphrase_salt,passphrase_hash,passphrase_iterations,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url,state_version,created_at,updated_at,deleted_at FROM links WHERE slug=? AND deleted_at IS NULL LIMIT 1`).bind(slug).first<Link>(); }
async function getManageLink(env: Env, slug: string, key: string): Promise<Link | null> { const link = await getLinkBySlug(env, slug); return link && await timingSafeStringEqual(key, link.manage_key) ? link : null; }
const audienceColumns = "id,parent_link_id,slug,label,expires_at,ended_message,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url,state_version,created_at,updated_at,deleted_at";
async function getAudienceEntries(env: Env, parentLinkId: number): Promise<AudienceEntry[]> { const result = await env.DB.prepare(`SELECT ${audienceColumns} FROM audience_entries WHERE parent_link_id=? AND deleted_at IS NULL ORDER BY created_at ASC,id ASC`).bind(parentLinkId).all<AudienceEntry>(); return result.results; }
async function getAudienceEntry(env: Env, parentLinkId: number, id: number): Promise<AudienceEntry | null> { return env.DB.prepare(`SELECT ${audienceColumns} FROM audience_entries WHERE id=? AND parent_link_id=? AND deleted_at IS NULL LIMIT 1`).bind(id, parentLinkId).first<AudienceEntry>(); }
async function getAudiencePublicTarget(env: Env, slug: string): Promise<PublicTarget | null> {
  const row = await env.DB.prepare(`SELECT l.id AS parent_id,l.slug AS parent_slug,l.target_url,l.manage_key,l.one_time,l.used_at,l.max_open_count,l.open_count,l.limit_reached_target_url,l.scheduled_target_url,l.switch_at,l.unlock_at,l.expires_at AS parent_expires_at,l.ended_message AS parent_ended_message,l.receipt_required,l.receipt_confirmed_at,l.passphrase_salt,l.passphrase_hash,l.passphrase_iterations,l.share_card_enabled AS parent_share_card_enabled,l.share_card_title AS parent_share_card_title,l.share_card_description AS parent_share_card_description,l.preview_mode AS parent_preview_mode,l.og_title AS parent_og_title,l.og_description AS parent_og_description,l.og_image_url AS parent_og_image_url,l.state_version AS parent_state_version,l.created_at AS parent_created_at,l.updated_at AS parent_updated_at,l.deleted_at AS parent_deleted_at,e.id AS entry_id,e.slug AS entry_slug,e.label,e.expires_at,e.ended_message,e.share_card_enabled AS entry_share_card_enabled,e.share_card_title AS entry_share_card_title,e.share_card_description AS entry_share_card_description,e.preview_mode AS entry_preview_mode,e.og_title AS entry_og_title,e.og_description AS entry_og_description,e.og_image_url AS entry_og_image_url,e.state_version AS entry_state_version,e.created_at AS entry_created_at,e.updated_at AS entry_updated_at,e.deleted_at AS entry_deleted_at FROM audience_entries e JOIN links l ON l.id=e.parent_link_id WHERE e.slug=? AND e.deleted_at IS NULL AND l.deleted_at IS NULL LIMIT 1`).bind(slug).first<Record<string, unknown>>();
  if (!row) return null;
  const link: Link = { id: Number(row.parent_id), slug: String(row.parent_slug), target_url: String(row.target_url), manage_key: String(row.manage_key), one_time: Number(row.one_time), used_at: row.used_at as string | null, max_open_count: row.max_open_count as number | null, open_count: Number(row.open_count), limit_reached_target_url: row.limit_reached_target_url as string | null, scheduled_target_url: row.scheduled_target_url as string | null, switch_at: row.switch_at as string | null, unlock_at: row.unlock_at as string | null, expires_at: row.parent_expires_at as string | null, ended_message: row.parent_ended_message as string | null, receipt_required: Number(row.receipt_required), receipt_confirmed_at: row.receipt_confirmed_at as string | null, passphrase_salt: row.passphrase_salt as string | null, passphrase_hash: row.passphrase_hash as string | null, passphrase_iterations: row.passphrase_iterations as number | null, share_card_enabled: Number(row.parent_share_card_enabled), share_card_title: row.parent_share_card_title as string | null, share_card_description: row.parent_share_card_description as string | null, preview_mode: row.parent_preview_mode as PreviewMode, og_title: row.parent_og_title as string | null, og_description: row.parent_og_description as string | null, og_image_url: row.parent_og_image_url as string | null, state_version: Number(row.parent_state_version), created_at: String(row.parent_created_at), updated_at: row.parent_updated_at as string | null, deleted_at: row.parent_deleted_at as string | null };
  const entry: AudienceEntry = { id: Number(row.entry_id), parent_link_id: link.id, slug: String(row.entry_slug), label: String(row.label), expires_at: row.expires_at as string | null, ended_message: row.ended_message as string | null, share_card_enabled: Number(row.entry_share_card_enabled), share_card_title: row.entry_share_card_title as string | null, share_card_description: row.entry_share_card_description as string | null, preview_mode: row.entry_preview_mode as PreviewMode, og_title: row.entry_og_title as string | null, og_description: row.entry_og_description as string | null, og_image_url: row.entry_og_image_url as string | null, state_version: Number(row.entry_state_version), created_at: String(row.entry_created_at), updated_at: row.entry_updated_at as string | null, deleted_at: row.entry_deleted_at as string | null };
  return { link, entry, slug };
}

async function handleHome(request: Request, env: Env): Promise<Response> { const error = new URL(request.url).searchParams.get("error") ?? undefined; return renderHome(request, env, error); }
async function handleSlugAvailability(request: Request, env: Env): Promise<Response> { const slug = normalizeSlugInput(new URL(request.url).searchParams.get("slug") ?? ""); if (!isValidSlug(slug)) return jsonResponse({ available: false, message: "使えない短縮パスです。" }); const issued = await env.DB.prepare("SELECT 1 FROM issued_slugs WHERE slug = ? LIMIT 1").bind(slug).first(); return jsonResponse(issued ? { available: false, message: "この短縮パスは使用できません。" } : { available: true, message: "この短縮パスは使用できます。" }); }
async function handleCreate(request: Request, env: Env): Promise<Response> {
  const form = await request.formData();
  if (!(await verifyTurnstile(getNullableFormText(form, "cf-turnstile-response"), request, env))) return renderCreateErrorPage("認証に失敗しました。もう一度試してください。", "");
  const parsed = await parseLinkValues(form, request, true); if ("error" in parsed) return renderCreateErrorPage(parsed.error);
  const initialAudience = hasInitialAudienceValues(form) ? await parseAudienceValues(form, request, parsed.values.targetUrl, isScheduledTargetConfigured(parsed.values.scheduledTargetUrl, parsed.values.switchAt)) : null;
  if (initialAudience && "error" in initialAudience) return renderCreateErrorPage(initialAudience.error);
  try {
    const link = await createLink(env, parsed.values, initialAudience?.values ?? null);
    return renderCreatedPage(buildShortUrl(request, link.slug), buildManageUrl(request, link.slug, link.manage_key), link);
  } catch (error) { if (error instanceof SlugUnavailableError) return renderCreateErrorPage("この短縮パスはすでに使われています。"); throw error; }
}

async function handlePublicGet(request: Request, env: Env, slug: string): Promise<Response> {
  const target = await requirePublicTarget(env, slug); if (target instanceof Response) return target;
  const { link, entry } = target; const previewMode = isScheduledTargetConfigured(link.scheduled_target_url, link.switch_at) ? "none" : (entry?.preview_mode ?? link.preview_mode);
  if (isPreviewRequest(request)) { if (isOpenLimitReached(link)) return renderTerminalUnavailable(terminalMessageFor(target)); if (previewMode === "none" || isLocked(link) || Boolean(link.passphrase_hash)) return renderPreviewUnavailable(); return renderOgPreview(request, target); }
  if (isLocked(link)) return renderLockedPage(link.unlock_at!);
  if (link.passphrase_hash && !(await hasUnlockCookie(request, target))) return renderPassphrasePage(target);
  if (isOpenLimitReached(link)) return renderLimitReachedResponse(target);
  return consumeOpenAndRedirect(request, env, target);
}
async function handleUnlock(request: Request, env: Env, slug: string): Promise<Response> {
  const target = await requirePublicTarget(env, slug); if (target instanceof Response) return target; const { link } = target;
  if (isLocked(link)) return renderLockedPage(link.unlock_at!);
  const passphrase = getFormText(await request.formData(), "passphrase");
  if (!passphrase || !(await matchesPassphrase(link, passphrase))) return renderPassphrasePage(target, "合言葉が正しくありません。");
  const expiresAt = Math.floor(Date.now() / 1000) + UNLOCK_COOKIE_SECONDS; const token = await makeUnlockToken(target, expiresAt); const headers = new Headers();
  headers.append("Set-Cookie", `${unlockCookieName(target.slug)}=${token}; Max-Age=${UNLOCK_COOKIE_SECONDS}; Path=/; HttpOnly; SameSite=Lax${new URL(request.url).protocol === "https:" ? "; Secure" : ""}`);
  return redirectResponse(buildShortUrl(request, target.slug), headers);
}
async function consumeOpenAndRedirect(request: Request, env: Env, initialTarget: PublicTarget): Promise<Response> {
  let target = initialTarget;
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const { link, entry } = target;
    if (isLocked(link)) return renderLockedPage(link.unlock_at!);
    if (link.passphrase_hash && !(await hasUnlockCookie(request, target))) return renderPassphrasePage(target);
    if (isOpenLimitReached(link)) return renderLimitReachedResponse(target);
    const destinationKind = activeDestinationKind(link);
    if (!hasOpenLimit(link)) return redirectResponse(destinationForKind(link, destinationKind));
    const opened = await env.DB.prepare(`UPDATE links SET open_count=open_count+1,used_at=CASE WHEN open_count+1>=max_open_count THEN CURRENT_TIMESTAMP ELSE used_at END WHERE id=? AND deleted_at IS NULL AND state_version=? AND (expires_at IS NULL OR julianday(expires_at)>julianday(?)) AND open_count<max_open_count AND (? IS NULL OR EXISTS (SELECT 1 FROM audience_entries WHERE id=? AND parent_link_id=links.id AND deleted_at IS NULL AND state_version=? AND (expires_at IS NULL OR julianday(expires_at)>julianday(?)))) RETURNING id,slug,target_url,manage_key,one_time,used_at,max_open_count,open_count,limit_reached_target_url,scheduled_target_url,switch_at,unlock_at,expires_at,ended_message,receipt_required,receipt_confirmed_at,passphrase_salt,passphrase_hash,passphrase_iterations,share_card_enabled,share_card_title,share_card_description,preview_mode,og_title,og_description,og_image_url,state_version,created_at,updated_at,deleted_at`).bind(link.id, link.state_version, new Date().toISOString(), entry?.id ?? null, entry?.id ?? null, entry?.state_version ?? null, new Date().toISOString()).first<Link>();
    if (opened) return redirectResponse(destinationForKind(opened, destinationKind));
    const refreshed = await requirePublicTarget(env, target.slug); if (refreshed instanceof Response) return refreshed; target = refreshed;
  }
  return renderErrorPage(409, "Conflict", "リンク設定が更新されました。もう一度開いてください。");
}
async function requirePublicTarget(env: Env, slug: string): Promise<PublicTarget | Response> {
  if (!isValidSlug(slug)) return renderErrorPage(404, "Not Found", "この短縮URLは存在しません。");
  const link = await getLinkBySlug(env, slug); if (link) return isLinkExpired(link) ? renderTerminalUnavailable(link.ended_message) : { link, entry: null, slug };
  const entryTarget = await getAudiencePublicTarget(env, slug); if (!entryTarget) return renderErrorPage(404, "Not Found", "この短縮URLは存在しません。");
  if (isLinkExpired(entryTarget.link)) return renderTerminalUnavailable(entryTarget.link.ended_message);
  if (isEntryExpired(entryTarget.entry!)) return renderTerminalUnavailable(entryTarget.entry!.ended_message);
  return entryTarget;
}
function terminalMessageFor(target: PublicTarget): string | null { return target.entry?.ended_message ?? target.link.ended_message; }
function renderLimitReachedResponse(target: PublicTarget): Response { return target.link.limit_reached_target_url ? redirectResponse(target.link.limit_reached_target_url) : renderTerminalUnavailable(terminalMessageFor(target)); }
function activeDestinationKind(link: Link): DestinationKind { return link.scheduled_target_url && link.switch_at && Date.parse(link.switch_at) <= Date.now() ? "scheduled" : "primary"; }
function destinationForKind(link: Link, kind: DestinationKind): string { return kind === "scheduled" && link.scheduled_target_url ? link.scheduled_target_url : link.target_url; }
function activeDestination(link: Link): string { return destinationForKind(link, activeDestinationKind(link)); }
function isLocked(link: Link): boolean { return Boolean(link.unlock_at && Date.parse(link.unlock_at) > Date.now()); }
function isLinkExpired(link: Link): boolean { return Boolean(link.expires_at && Date.parse(link.expires_at) <= Date.now()); }
function isEntryExpired(entry: AudienceEntry): boolean { return Boolean(entry.expires_at && Date.parse(entry.expires_at) <= Date.now()); }
